window.STORY_CHAPTERS["c2dc4a5a61f7df854"]={"id":"c2dc4a5a61f7df854","lines":[{"uid":"talk.vc.home_touch_kirito_sao_2nd_anniv_7#originalText","id":"talk.vc.home_touch_kirito_sao_2nd_anniv_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不，我很欢迎妳进一步交流，只不过，还是到气氛好一点的地方……","en":"Don't get me wrong, I'm a huge fan of open communication. It's just... there's a time and place.","ja":"いや、コミュニケーションは大歓迎なんだ。ただ、もうちょっと雰囲気のあるところで……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_sao_2nd_anniv_8#originalText","id":"talk.vc.home_touch_kirito_sao_2nd_anniv_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喂喂，妳该不会是想对我发起决斗吧？我可不想跟妳交手啊。","en":"Wait a minute, I hope you're not challenging me to a duel? I don't want to fight you.","ja":"おいおい、まさかデュエルを申し込んでくる気じゃないだろうな?君とは戦いたくないよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_sao_2nd_anniv_1#originalText","id":"talk.vc.home_time_kirito_sao_2nd_anniv_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"呼啊……现在几点？今天没什么安排，让我悠哉地睡吧。","en":"Yawwwn... What time is it? I've got no plans today. Just lemme sleep in.","ja":"ふわああ……今何時だ?今日は何の予定もないんだゆっくり寝かせてくれよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_sao_2nd_anniv_2#originalText","id":"talk.vc.home_time_kirito_sao_2nd_anniv_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"难不成妳做了早餐给我吗！？妳做的菜无论何时都令我食指大动。那么，我要开动了～！","en":"Oh, you brought me breakfast?! I'm always happy to eat what you've made!","ja":"もしかして、朝食の差し入れか!?君の料理ならいつでも大歓迎だそれじゃ、いただきまーす!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_sao_2nd_anniv_3#originalText","id":"talk.vc.home_time_kirito_sao_2nd_anniv_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"早安……不，我现在才正要去睡，不小心打怪打得太投入了……","en":"Good morn...er, goodnight actually. I'm about to turn in. I was so focused on hunting, I couldn't stop...","ja":"おはよう……いや、俺はこれから寝るところなんだつい狩りに夢中になっちゃってな……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_sao_2nd_anniv_4#originalText","id":"talk.vc.home_time_kirito_sao_2nd_anniv_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗯～天气真棒，拿来午睡再适合不过了。妳不介意的话，要不要一起睡？","en":"Mmm, what lovely weather. Just perfect for a nap! Wanna join me?","ja":"うーん、いい天気だ絶好の昼寝日和だなよかったら、一緒に寝るか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_sao_2nd_anniv_5#originalText","id":"talk.vc.home_time_kirito_sao_2nd_anniv_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"白天走那个小巷还是很危险喔。我就认识好几个人进去后便困在里面了。","en":"That alley is dangerous, even in daylight. I know too many people that never made it out.","ja":"その路地は昼間でも危ないぜ出てこられなくなったヤツを何人も知ってるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_sao_2nd_anniv_6#originalText","id":"talk.vc.home_time_kirito_sao_2nd_anniv_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"就算在VR的世界里，做日光浴还是让人觉得很舒服呢。这到底是什么原理啊？","en":"The sun feels so good, even in VR. I wonder how they programmed it?","ja":"VRの世界でも、太陽の光は浴びると気持ちいいよなどういう仕組みなんだろう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_sao_2nd_anniv_7#originalText","id":"talk.vc.home_time_kirito_sao_2nd_anniv_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"晚上到《圈外》还是很危险，如果妳打算外出，我也陪妳一起去吧。","en":"Going out of range at night is just too dangerous. If you're going out, I'm coming with you.","ja":"夜の《圏外》はやっぱり危険だもし外に出るつもりなら俺も一緒について行くよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_sao_2nd_anniv_8#originalText","id":"talk.vc.home_time_kirito_sao_2nd_anniv_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天的狩猎很成功呢！好，我们接下来去举杯庆祝吧。我知道有间店好吃又便宜喔。","en":"We sure got a great haul on today's hunt! This calls for a celebration. I know a tasty, cheap restaurant!","ja":"今日の狩りはバッチリ成功だったな!よし、これから祝杯といこうぜうまくて安い店を知ってるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_sao_2nd_anniv_9#originalText","id":"talk.vc.home_time_kirito_sao_2nd_anniv_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"妳已经困了吗？夜晚才正要开始呢，我们再多聊一会儿吧。","en":"Sleepy already? But the night's still young! C'mon, let's talk some more.","ja":"もう眠いのか?夜はまだまだこれからじゃないかもう少しおしゃべりしようぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_sao_2nd_anniv_10#originalText","id":"talk.vc.home_time_kirito_sao_2nd_anniv_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……妳睡不着吗？勉强自己尽量多睡点比较好喔。毕竟这真的攸关性命啊。","en":"Can't sleep? You should, though. It could mean the difference between life and death.","ja":"……眠れないのか?無理してでも寝ておいた方がいいぞそれこそ命に関わるからな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_sao_2nd_anniv_11#originalText","id":"talk.vc.home_time_kirito_sao_2nd_anniv_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"入夜之后，我总会忍不住想起许多事。就算尽量不去思考，还是会不断浮现在脑海里。","en":"When it's night, my mind always conjures up bad memories. I try to stop them, but I just can't.","ja":"夜になると、いろいろ思い出してしまう。考えないようにしていてもどうしても頭に浮かんでくるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_sao_2nd_anniv_12#originalText","id":"talk.vc.home_time_kirito_sao_2nd_anniv_12","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"会不会明天一觉醒来，就发现自己躺在家里的床上呢……我以前很常这么想呢。","en":"At the start, I used to wonder if I'd wake up in my own bed at home the next morning... I was so naive.","ja":"明日目が覚めたら、自宅のベッドの上だったりしないかな……なんて以前はよく考えたよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_sao_2nd_anniv_1#originalText","id":"talk.vc.home_day_kirito_sao_2nd_anniv_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"到了星期一也不用上学，果然让人心情轻松不少呢。","en":"I guess one upside to being here is there's no school on Monday.","ja":"月曜になっても、学校行かなくていいっていうのは、やっぱり気が楽だよな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_sao_2nd_anniv_2#originalText","id":"talk.vc.home_day_kirito_sao_2nd_anniv_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我已经在VR的世界里待了好久，越来越不清楚今天是星期几了。","en":"We've been in VR so long the days of the week no longer have meaning.","ja":"もうずっとVRの中にいるから曜日の感覚は薄くなってきたよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_sao_2nd_anniv_3#originalText","id":"talk.vc.home_day_kirito_sao_2nd_anniv_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"虽然平常没怎么留意，但只要一知道今天是假日，总觉得心情就会特别愉快呢。","en":"When I realize it's a holiday IRL, I always feel happy for some reason.","ja":"普段は意識してないけど休みの日だってわかるとなんとなく気分が浮かれてくるよな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_sao_2nd_anniv_4#originalText","id":"talk.vc.home_day_kirito_sao_2nd_anniv_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"就算在星期日的深夜迟迟不睡，也越来越没有罪恶感了。回到现实后八成会很痛苦吧。","en":"Not even staying up late on Sunday makes me feel guilty anymore... I don't think I can go back.","ja":"日曜の深夜に起きてるのも罪悪感が薄くなってきた現実に戻ったら大変だな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_sao_2nd_anniv_1#originalText","id":"talk.vc.home_event_kirito_sao_2nd_anniv_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"新年快乐。我们今年一定要一起将这个死亡游戏破关！","en":"Happy New Year! Okay, this's the year we're finally making it out of this death game!","ja":"あけましておめでとう今年こそは、このデスゲームを一緒にクリアしようぜ!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_sao_2nd_anniv_2#originalText","id":"talk.vc.home_event_kirito_sao_2nd_anniv_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我觉得节分不太符合游戏的世界观，但都有拿刀的武士了，这样一想好像也还能接受。","en":"Setsubun doesn't seem to go with this world's aesthetic, but I guess I could picture a Samurai here.","ja":"節分、なんてあんまり世界観に合わない気がしてたけど刀持った侍がいるならアリなのか"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_sao_2nd_anniv_3#originalText","id":"talk.vc.home_event_kirito_sao_2nd_anniv_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"情人节啊……不，我没在期待啦。只不过，这种日子妳跟我待在一起，没问题吗……？","en":"So V-Day... Oh, no, I wasn't hinting at anything. It's just...are you sure you want to spend the day with me?","ja":"バレンタインか……いや、別に期待してるわけじゃない。ただ、こんな日に俺と一緒にいていいのか……?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_sao_2nd_anniv_4#originalText","id":"talk.vc.home_event_kirito_sao_2nd_anniv_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"每次到了女儿节，我就会想起我的妹妹。希望她过得平安。","en":"Hinamatsuri always makes me think of my sister. I hope she's doing okay.","ja":"ひな祭りになると、妹のことを思い出すんだ。元気にしててくれればいいんだけど"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_sao_2nd_anniv_5#originalText","id":"talk.vc.home_event_kirito_sao_2nd_anniv_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这个……算是回礼。既然收了妳送的礼，我要是一点表示都没有，不就太失礼了？","en":"Here's, uh...my thank-you gift. You know, since you gave me a Valentine, and all.","ja":"これ、一応……お礼もらったからには、ちゃんと返さないと申し訳ないだろ?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_sao_2nd_anniv_6#originalText","id":"talk.vc.home_event_kirito_sao_2nd_anniv_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"太好了，总算遇到感觉不会骗我的人了。今天真的是走到哪被骗到哪啊。","en":"Thank heavens I finally met someone who won't play along on April Fools. Liars are everywhere today.","ja":"よかった、やっと嘘をつかなそうな人に巡り会えたよ今日はどこも嘘つきばっかりだ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_sao_2nd_anniv_7#originalText","id":"talk.vc.home_event_kirito_sao_2nd_anniv_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"连假就是打宝练功的好时机，因为会开很多报酬优渥的任务和活动。","en":"Long vacations are for grinding. So many high-reward quests and events to try out.","ja":"連休中は稼ぎ時だ割のいいクエストやイベントがたくさん出るだろうからな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_sao_2nd_anniv_8#originalText","id":"talk.vc.home_event_kirito_sao_2nd_anniv_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"都已经跑到VR的世界里了，干嘛还设置梅雨季这种东西啊……","en":"Who goes out of their way to program rainy season into a VR world? I wish they hadn't...","ja":"せっかくVRの中にいるんだから梅雨なんて設定はなしにすればいいのにな……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_sao_2nd_anniv_9#originalText","id":"talk.vc.home_event_kirito_sao_2nd_anniv_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不晓得《SAO》的世界是不是也有竹子。有的话，或许能趁活动大捞一笔呢……","en":"I wonder if SAO has bamboo? If so, somebody could profit off a Tanabata event.","ja":"《SAO》の世界にも、竹ってあるのかな。あるなら、イベントに乗じて一儲けできるかも……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_sao_2nd_anniv_10#originalText","id":"talk.vc.home_event_kirito_sao_2nd_anniv_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"在湖里游泳是很舒服没错，但要小心水栖怪物喔。","en":"A swim in the lake sounds nice and all, but watch out for aquatic monsters, okay?","ja":"湖で泳ぐのは気持ちいいと思うけど、水棲モンスターには十分気をつけてくれよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_sao_2nd_anniv_11#originalText","id":"talk.vc.home_event_kirito_sao_2nd_anniv_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"就算是在虚拟世界，夏天的尾声还是会让人感到哀伤。这是为什么呢……","en":"Even in a virtual world, summer's end still feels a little melancholy. I wonder why that is?","ja":"仮想の世界でも、夏の終わりはなんとなくもの悲しいどうしてだろうな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_sao_2nd_anniv_12#originalText","id":"talk.vc.home_event_kirito_sao_2nd_anniv_12","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"既然这个世界做得如此精致，说不定那个月亮也是游戏空间呢……我说笑的。","en":"With this world as elaborately-built as it is, I wouldn't be surprised if the moon were also a field...haha.","ja":"これだけ精巧に作られた世界ならあの月も、ちゃんとフィールドになってるのかも……なんてな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_sao_2nd_anniv_13#originalText","id":"talk.vc.home_event_kirito_sao_2nd_anniv_13","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"万圣节……虽然我在现实中不太在意这个节日，但作为游戏活动还挺有趣的呢。","en":"Halloween... I was never really a fan IRL, but Halloween events in games are pretty fun.","ja":"ハロウィン……現実ではあんまり意識してなかったけど、ゲームのイベントとしては面白いな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_sao_2nd_anniv_14#originalText","id":"talk.vc.home_event_kirito_sao_2nd_anniv_14","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"每到这个日子，我就会再次想起被关在游戏里那天的绝望，以及朝向破关迈进的决心。","en":"This day always gives me flashbacks. Of the despair I felt being trapped and the determination to win.","ja":"この日になると、改めて思い出すよ閉じ込められた日の絶望とクリアを目指す決意を"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_sao_2nd_anniv_15#originalText","id":"talk.vc.home_event_kirito_sao_2nd_anniv_15","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"虽然圣诞节这天的回忆让我有些五味杂陈……但我觉得，跟妳在一起的话，应该能开心度过。","en":"I have a complicated history with Christmas...but I think it'll be a merry one, if I'm with you.","ja":"クリスマスには、少し複雑な思い出があるけど……君と一緒にいれば、ちゃんと楽しめそうだ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_sao_2nd_anniv_1#originalText","id":"talk.vc.home_season_kirito_sao_2nd_anniv_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我觉得春天午睡是最舒服的。正所谓「春眠不觉晓」，对吧？","en":"You know the saying, \"In spring, one sleeps a sleep that knows no dawn?\" Well, it's totally true.","ja":"昼寝は、春が一番気持ちいいな春眠、暁を覚えずって言うだろ?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_sao_2nd_anniv_2#originalText","id":"talk.vc.home_season_kirito_sao_2nd_anniv_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"虽然我对洗澡没什么讲究，但我也能体会在炎炎夏日冲冷水澡的畅快感。","en":"I'm not a big bath-person, but I do appreciate a nice cold shower on a hot summer day.","ja":"風呂にはあんまりこだわらないけど夏の暑い日に、冷たいシャワーを浴びる気持ちよさはわかる"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_sao_2nd_anniv_3#originalText","id":"talk.vc.home_season_kirito_sao_2nd_anniv_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"艾恩葛朗特的餐厅也越开越多间了呢。看来这下能好好享受食欲之秋了。","en":"With all these new restaurants popping up in Aincrad, we'll have our \"Autumn of Appetite\" after all.","ja":"アインクラッドにも、食事の店が増えてきたよな。これなら食欲の秋も楽しめそうだ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_sao_2nd_anniv_4#originalText","id":"talk.vc.home_season_kirito_sao_2nd_anniv_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我虽然不太喜欢冷天，但早起时的冷冽空气，我还挺中意的。","en":"I don't like winter, but I actually kinda like that first breath of crisp air in the morning.","ja":"寒い日は基本的に苦手だけど朝早く起きた時の冷たい空気はわりと好きかも"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_sao_2nd_anniv_2#originalText","id":"talk.vc.home_bd_kirito_sao_2nd_anniv_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"谢谢妳帮我庆生，真没想到会有人为我过生日……我非常高兴喔。","en":"Aw, thanks! I didn't think anyone would remember my birthday... I'm really touched.","ja":"祝ってくれてありがとうまさか、お祝いしてもらえるなんて思ってなくて……すごくうれしいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_sao_2nd_anniv_4#originalText","id":"talk.vc.home_bd_kirito_sao_2nd_anniv_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天是尤吉欧的生日喔。在这个世界的话，他比较适合哪种剑呢？","en":"It's Eugeo's birthday. I wonder, what kind of sword would he use in this world?","ja":"今日はユージオの誕生日なんだこの世界だったら、あいつにはどんな剣が似合うかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_sao_2nd_anniv_5#originalText","id":"talk.vc.home_bd_kirito_sao_2nd_anniv_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天是爱丽丝的生日呢。找个风景优美的地方，大家一起帮她庆祝吧。","en":"It's Alice's birthday. Let's find a place with a great view and invite the gang to celebrate!","ja":"今日はアリスの誕生日だな景色のいい場所に行ってみんなでお祝いしようぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_sao_2nd_anniv_6#originalText","id":"talk.vc.home_bd_kirito_sao_2nd_anniv_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天是亚丝娜的生日，我准备了礼物要给她惊喜……能顺利送出去吗？","en":"It's Asuna's birthday. I got her a gift as a surprise... Hope I muster up the courage to give it to her.","ja":"今日はアスナの誕生日だサプライズでプレゼントを用意してるんだけど……渡せるかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_sao_2nd_anniv_7#originalText","id":"talk.vc.home_bd_kirito_sao_2nd_anniv_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天是我妹妹的生日喔。虽然她本人不在这里……不过，如果妳不介意，可以陪我一起庆祝吗？","en":"It's my sister's birthday today, but she's not here... Wanna celebrate with me anyway?","ja":"今日は妹の誕生日なんだ本人はいないけど……よかったら一緒に祝ってくれないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_sao_2nd_anniv_8#originalText","id":"talk.vc.home_bd_kirito_sao_2nd_anniv_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"诗乃的生日，该送她什么才好啊？这个世界又没有枪，什么才会让她高兴呢？","en":"Since this world doesn't have guns, what should I get Sinon for her birthday? What would she even like?","ja":"シノンの誕生日、どうしようかなまさか、この世界に銃はないし何が喜ぶかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_sao_2nd_anniv_9#originalText","id":"talk.vc.home_bd_kirito_sao_2nd_anniv_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天是有纪的生日对吧？一起去帮她庆生吧，她一定会很高兴的喔。","en":"It's Yuuki's birthday today, right? You should go be with her. I know she'd love that.","ja":"今日はユウキの誕生日だろ?お祝いに行ってあげなよきっとすごく喜ぶぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_sao_2nd_anniv_14#originalText","id":"talk.vc.home_bd_kirito_sao_2nd_anniv_14","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"莉兹的生日是今天对吧？我们一起去帮她庆祝吧。","en":"It's Liz's birthday today, right? Want to go do something with her?","ja":"リズは今日が誕生日なんだろふたりでお祝いしに行こうか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_kirito_sao_2nd_anniv_15#originalText","id":"talk.vc.home_bd_kirito_sao_2nd_anniv_15","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天是西莉卡的生日喔。我想准备礼物送她，送什么才能让她开心呢？","en":"It's Silica's birthday today. I want to get her a present, but I'm not sure what she'd like.","ja":"今日はシリカの誕生日なんだプレゼントを贈ろうと思うんだけど何が喜ばれるかな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kirito_sao_2nd_anniv_1#originalText","id":"talk.vc.home_etc_kirito_sao_2nd_anniv_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喔喔，通过任务了啊！报酬是什么？是不是收到了什么好东西？","en":"You cleared the quest? That's great! What was your reward? Get anything good?","ja":"おお、クエストクリアしたのか!報酬はなんだった?いい物が手に入ったんじゃないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kirito_sao_2nd_anniv_2#originalText","id":"talk.vc.home_etc_kirito_sao_2nd_anniv_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好像有礼物要给妳喔。要不要确认一下收到了什么？","en":"You've got a present. Wanna open it and see what it is?","ja":"君にプレゼントが届いてるみたいだ何が贈られてきたのか確認してみたらどうだ?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kirito_sao_2nd_anniv_3#originalText","id":"talk.vc.home_etc_kirito_sao_2nd_anniv_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喂，好像发现新任务了喔！赶紧去挑战看看吧！","en":"Hey, somebody found a new quest! Let's go try it out right away!","ja":"おい、新しいクエストが見つかったらしいぞ!さっそく挑戦しようぜ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_ggo_wizard_1#originalText","id":"talk.vc.home_wait_kirito_ggo_wizard_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"到底、是要怎么样、才会变成这个样子啊……","en":"How in the world did I end up in this outfit...","ja":"いったい、なにがどうなってこんな格好をすることに……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_ggo_wizard_2#originalText","id":"talk.vc.home_wait_kirito_ggo_wizard_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"魔、魔法少女桐人登场！……怎样啦！拜托不要用那种眼神看我啦。","en":"Here I am... As a witch! ...Don't look at me like that!","ja":"ま、魔法少女キリト参上!……なんだよそんな目で見ないでくれよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_ggo_wizard_3#originalText","id":"talk.vc.home_wait_kirito_ggo_wizard_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"如果是魔杖二刀流，魔法的威力是不是也会变成2倍呀？","en":"I wonder if my magic will double in power with my two-sword style.","ja":"ステッキ二刀流だと魔法の威力も2倍になったりしないのかな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_ggo_wizard_4#originalText","id":"talk.vc.home_wait_kirito_ggo_wizard_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"总觉得、脚下凉凉的很别扭无法保持冷静，防御力也好像很弱……","en":"I can't seem to get a good footing. I wonder if my defense is also weak...","ja":"なんだか、スースーして足元が落ち着かないな防御力も弱そうだし……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_ggo_wizard_5#originalText","id":"talk.vc.home_wait_kirito_ggo_wizard_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……意外地、不会穿帮的样子啊。总觉得上街后一定会被嘲笑什么的，结果没有任何人发现是我！","en":"...I'm surprised nobody's recognized me. I was sure people would have started laughing as soon as I arrive into town...","ja":"……案外、バレないもんだな街に出たら笑われるかと思ったけど誰も俺だって気付かなかったよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_ggo_wizard_6#originalText","id":"talk.vc.home_wait_kirito_ggo_wizard_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"只要被说可爱……除了全身窜起一股寒气以外，还混杂着一点快感……","en":"...Whenever someone calls me cute, it's a mixed bag... It feels both frigid yet thrilling...","ja":"……かわいい、って言われると寒気が走るのと同時に少しだけ快感が混ざってるんだ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_ggo_wizard_7#originalText","id":"talk.vc.home_wait_kirito_ggo_wizard_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"就只有我实在是太不公平了！之后一定也要让克莱因和艾基尔成为魔法少女！","en":"It's not fair that only I'm going through with this! Mark my words, Klein and Agil are next!","ja":"俺だけやるのは不公平だよなクラインやエギルにも後で絶対やらせてやる!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_ggo_wizard_8#originalText","id":"talk.vc.home_wait_kirito_ggo_wizard_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"现在就吃我一击！《星暴魔法急流》！","en":"Get a taste of this! Starburst Magical Stream!","ja":"今こそ食らいなさい!《スターバースト・マジカル・ストリーム》!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_ggo_wizard_9#originalText","id":"talk.vc.home_wait_kirito_ggo_wizard_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"拜托──把这打扮的我放置在这什么的，饶了我吧──","en":"Hey! Don't leave me in this outfit!","ja":"おーい、この格好で放置するのは勘弁してくれよー"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_ggo_wizard_1#originalText","id":"talk.vc.home_touch_kirito_ggo_wizard_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这发饰是很可爱啦，只要不是给我用，是给真正的女孩子的话啦。","en":"I think this hair accessory is cute. Of course not for me, but for an actual girl!","ja":"この髪飾りは、かわいいと思うよ俺じゃなくて、ちゃんと女の子が身につければ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_ggo_wizard_2#originalText","id":"talk.vc.home_touch_kirito_ggo_wizard_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"穿着这身打扮被摸头……总觉得有种无法用言语表达的感觉涌上心头。","en":"Whenever someone pets my head in this outfit... I can't explain it, but I just feel...","ja":"こ、この格好で頭を撫でられると……なんていうか、言葉で表現できない感情がわき上がってくる"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_ggo_wizard_4#originalText","id":"talk.vc.home_touch_kirito_ggo_wizard_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不、不要啦！？……不行了，我已经没救了……","en":"S-Stop it! ...I can't do it... I can't do it anymore!","ja":"い、いやん!?……ダメだ俺はもうダメだ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_ggo_wizard_5#originalText","id":"talk.vc.home_touch_kirito_ggo_wizard_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喂、喂喂！不要在那想知道衣服的构造进行调查什么啊，你、这是性骚扰吧？","en":"Hey, hey! Don't even think about looking at my outfit like that! That's harassment, no?","ja":"お、おいおい!服の構造を調べようとしないでくれそれって、セクハラなんじゃないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_ggo_wizard_1#originalText","id":"talk.vc.home_time_kirito_ggo_wizard_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"早安！魔、魔法少女桐人来叫赖床鬼起床啰！","en":"Good morning! Kirito...the witch is here to wake up you sleepyheads!","ja":"グッモーニン!ま、魔法少女キリトが寝ぼすけさんを起こしに来たよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_ggo_wizard_4#originalText","id":"talk.vc.home_time_kirito_ggo_wizard_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"穿、穿成这样到空间中实在是……至少让我拿着剑吧。","en":"Going into the battlefield in this outfit... At least give me a sword!","ja":"さ、さすがにこの格好でフィールドに出るのは……せめて剣は持たせてくれ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_ggo_wizard_7#originalText","id":"talk.vc.home_time_kirito_ggo_wizard_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"像现在这样两人一起用餐，应该会被当作女孩子们吧？总觉得不可思议呀。","en":"Having a meal with you makes me look more like a girl. What a weird turn of events.","ja":"こうやってふたりで食事してると女の子同士って思われてるのかななんだか不思議だよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_ggo_wizard_10#originalText","id":"talk.vc.home_time_kirito_ggo_wizard_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"夜晚人们的耳目比较少，反而会介意起……在这种阴暗的地方打扮成这样子的自己是怎么了啊。","en":"I met a couple of people during the day in this outfit, but I wonder what they would say at night?","ja":"夜は人目が少ない反面、暗い場所でこんな格好している自分ってなんだろう……って気になるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_tales_1#originalText","id":"talk.vc.home_wait_kirito_tales_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"在《ALO》里穿成这样感觉真新鲜，不过不能飞行不太方便。","en":"Dressing like this in ALO is giving me a whole new perspective. Too bad I can't fly, though.","ja":"《ALO》の中でこんな格好するのなんだか新鮮だな空を飛べないのは不便だけど"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_tales_2#originalText","id":"talk.vc.home_wait_kirito_tales_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"奥尔芬说他的世界里有个人声音跟我很像，真想和对方见上一面。","en":"There's a guy in Alphen's world who sounds like me. I'd kind of like to meet him.","ja":"アルフェンの世界には、俺に似た声の奴がいるって言ってたけどちょっと会ってみたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_tales_3#originalText","id":"talk.vc.home_wait_kirito_tales_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"如果奥尔芬手上拿的火焰之剑可以当成武器来用，大家应该都会很想要。","en":"If Alphen's flaming sword can actually be used as a weapon, I'll bet everyone wants it.","ja":"アルフェンの持ってる炎の剣もし武器として使えるならみんな欲しがりそうだな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_tales_4#originalText","id":"talk.vc.home_wait_kirito_tales_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"奥尔芬也很爱吃辣喔。我打算下次带他来趟超辣食物之旅。","en":"Alphen sure loves spicy food. Maybe I should take him on a spice tour.","ja":"アルフェンもなかなかの辛いもの好きだったぞ今度激辛巡りしようと思うんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_tales_5#originalText","id":"talk.vc.home_wait_kirito_tales_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"痛觉失效在游戏里很方便，但如果现实中真的变那样就糟了，可能会没注意到自己受了重伤。","en":"Feeling no pain is great in-game, but it would be horrible IRL. You'd keep walking on a broken leg.","ja":"痛覚無効ってゲームだと便利だけど実際にそうなったら大変だよな大怪我に気付けないとかありそうだし"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_tales_6#originalText","id":"talk.vc.home_wait_kirito_tales_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"奥尔芬似乎是个重度装备狂。他和莉兹应该会很聊得来吧。","en":"Alphen seems to be a real equipment junkie. He and Liz would probably get along great.","ja":"アルフェンはずいぶんな武具マニアみたいだリズと話が合いそうだな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_tales_7#originalText","id":"talk.vc.home_wait_kirito_tales_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我一开始见到奥尔芬时吓了一大跳，因为他半张脸都被面具遮着。","en":"When I first met Alphen, he scared me a little since his face is half-covered by a mask.","ja":"アルフェンを見た時、最初はびっくりしたよ。顔の半分が仮面で覆われてたからさ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_tales_8#originalText","id":"talk.vc.home_wait_kirito_tales_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"在那边的世界里似乎有可以较量剑技的修练场，真想去一趟看看。","en":"There's a training hall in their world where you can practice sword fighting. I'd love to go.","ja":"向こうの世界には、剣の腕を競う修練場っていう場所があるらしいちょっと行ってみたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_tales_9#originalText","id":"talk.vc.home_wait_kirito_tales_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"怎么了？穿着不习惯的打扮让妳累了吗？是的话就稍微休息一下吧。","en":"What's wrong? Is that new getup tiring you out? Then let's take a little break.","ja":"どうしたんだ?慣れない格好で疲れたのかだったら、少し休憩しようぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_tales_1#originalText","id":"talk.vc.home_touch_kirito_tales_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"将头发染上颜色，真是不习惯……我看起来是不是很怪？","en":"I'm not used to dying my hair... Do I look weird?","ja":"髪の毛に色を入れるってなんだか慣れないんだよな……俺、変じゃないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_tales_2#originalText","id":"talk.vc.home_touch_kirito_tales_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喂、喂……别这样一直摸我啦，奥尔芬他们在看耶。","en":"W-Whoa, there. Don't be so handsy. Alphen and Shionne are staring at us.","ja":"お、おい……そんなにペタペタ触るなってアルフェンたちが見てるだろ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_tales_4#originalText","id":"talk.vc.home_touch_kirito_tales_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这个放在肩膀上的狼很帅气吧！","en":"The wolf on my shoulder sure looks cool!","ja":"この肩についてる狼格好いいよな!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_tales_5#originalText","id":"talk.vc.home_touch_kirito_tales_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"感觉穿这身装备适合用《体术》战斗，很方便活动，我还满喜欢的。","en":"This seems like a weapon used with the Martial Art skill. It's so smooth, I actually like it.","ja":"なんだか《体術》で戦いそうな装備だよな動きやすくてわりと好きだぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_tales_6#originalText","id":"talk.vc.home_touch_kirito_tales_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这个花色是尾巴吗？这套服装的很多地方在设计上都融入了狼的特征，找起来满好玩的。","en":"Is this design made of tails? These costumes are just full of wolf motifs—I love spotting them.","ja":"この柄は尻尾かな?この衣装、色んな所に狼のモチーフが散りばめられてて、探すと面白いぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_tales_1#originalText","id":"talk.vc.home_time_kirito_tales_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"睡了一觉醒来，装备穿起来就相当习惯了，这样就能充分发挥实力战斗。","en":"Now that it's a new day, my costume doesn't feel strange anymore. Now I can definitely fight.","ja":"寝て起きたら、装備の違和感もなくなったよ。これならバッチリ戦えそうだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_tales_4#originalText","id":"talk.vc.home_time_kirito_tales_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好，带奥尔芬他们逛逛阿尔普海姆吧。毕竟这个世界也有很多景色优美的地方。","en":"Let's show Alphen and Shionne around Alfheim. This world sure has lots of pretty sights.","ja":"よし、アルフェンたちにアルヴヘイムを案内しようぜ。景色のいいところも多いからな、この世界は"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_tales_7#originalText","id":"talk.vc.home_time_kirito_tales_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天还是别再吃超辣食物好了。毫无喘息机会的话，希侬就太可怜了。","en":"I'll have to take a rain check on spicy food today. Poor Shionne needs a break, too.","ja":"さすがに、今日は激辛メニューはやめておくか。あんまり続くとシオンが可哀想だしな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_tales_10#originalText","id":"talk.vc.home_time_kirito_tales_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我看到奥尔芬和希侬两人在夜里悄悄谈话……真希望能尽早帮助他们回去。","en":"I saw Alphen and Shionne talking in hushed whispers late last night. I hope they make it home soon.","ja":"夜中、アルフェンとシオンがふたりで話してるのを見たんだ……早く帰してやりたいよな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_tales_1#originalText","id":"talk.vc.home_day_kirito_tales_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"奥尔芬他们的世界也有星期的概念吗？是不是同样觉得星期一很累人呢？","en":"Do you think Alphen's world has days? I guess Mondays are a drag no matter where you're from.","ja":"アルフェンたちの世界にも曜日ってあるんだろうかやっぱ月曜はきついのかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_tales_2#originalText","id":"talk.vc.home_day_kirito_tales_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"换了身打扮后，就算做的事一如往常，还是会感到很新鲜。","en":"Everything feels so fresh and fun when you're wearing a new outfit.","ja":"格好が変わると、同じことをしててもなんだか新鮮だな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_tales_3#originalText","id":"talk.vc.home_day_kirito_tales_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好，总算放假了。这样一整天就能帮忙奥尔芬他们了。","en":"Good. It's finally vacation. Now I can spend the whole day helping Alphen and Shionne.","ja":"よし、やっと休みだなこれで一日中、アルフェンたちの手伝いができるってもんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_tales_4#originalText","id":"talk.vc.home_day_kirito_tales_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"希望下星期就能让奥尔芬他们回到原来的世界。","en":"I hope we can manage to send Alphen and Shionne back to their world by next week.","ja":"来週には、なんとかアルフェンたちを元の世界へ帰してやりたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_tales_1#originalText","id":"talk.vc.home_season_kirito_tales_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好，邀奥尔芬和希侬去赏花吧！当然，一定要带赏花便当！","en":"Let's invite Alphen and Shionne on a Hanami picnic! We'll pack a sakura-themed lunch, of course!","ja":"よし、アルフェンとシオン誘ってお花見しようぜ!もちろん、お花見弁当持ってな!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_tales_2#originalText","id":"talk.vc.home_season_kirito_tales_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不管多热，奥尔芬看起来都丝毫不受影响。在夏天真羡慕他。","en":"Alphen always looks comfortable, no matter how hot it is. I wish I were him in the summer. ","ja":"アルフェンはどんなに暑くても全然平気そうなんだよな夏は羨ましいぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_tales_3#originalText","id":"talk.vc.home_season_kirito_tales_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那边的世界里似乎有个国家，领土内全是森林。秋天叶子转红时，景色肯定很壮观。","en":"I hear their world is very woodsy. The views must be breathtaking in the fall.","ja":"向こうは国中が森っていう場所もあるみたいだ紅葉したらすごい眺めだろうな"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_tales_4#originalText","id":"talk.vc.home_season_kirito_tales_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这个世界的冬天已经够严酷了，居然还有整年都是寒冬的世界……光是想像，我就快全身发抖了。","en":"Winters here are hard enough. But a world where it's always cold? Just the thought makes me shiver.","ja":"この世界の冬でもきついのに一年中寒い世界なんて……想像しただけで体が震えそうだ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kirito_tales_1#originalText","id":"talk.vc.home_etc_kirito_tales_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好，通过任务了！距离奥尔芬他们回归原本世界，又更近了一步！","en":"Quest cleared! We're a step closer to getting Alphen and Shionne home!","ja":"よし、クエストクリア!また一歩、アルフェンたちの帰還に近づいたな!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kirito_tales_2#originalText","id":"talk.vc.home_etc_kirito_tales_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好像有礼物送到了。我建议妳早点确认比较好喔！说不定是重要的东西。","en":"I think you've got a present. You should check it ASAP. It might be important.","ja":"プレゼントが来てるみたいだぞ早めに確認した方がいいんじゃないか大事なものかもしれないし"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_kirito_tales_3#originalText","id":"talk.vc.home_etc_kirito_tales_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"下个任务会是什么呢？邀奥尔芬他们一起挑战看看好了。","en":"I wonder what the next quest is? We should ask Alphen and Shionne to join us.","ja":"次のクエストはなんだろうなアルフェンたちを誘ってチャレンジしてみようぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_kirito_alo_wedding_wait_1#originalText","id":"talk.vc.home_kirito_alo_wedding_wait_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"有点静不下心呀……有没有哪里看起来很怪呀？","en":"I can't stand still... Isn't there something a bit off?","ja":"ちょっと落ち着かないな……どっか変じゃないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_kirito_alo_wedding_wait_2#originalText","id":"talk.vc.home_kirito_alo_wedding_wait_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……啊、抱歉。总觉得，很紧张。应该是因为这身衣服吧。","en":"...Ah, I'm sorry. I got a little nervous. I think it's because of this outfit.","ja":"……あぁ、ごめん\u0003なんだか、緊張しちゃってこの格好のせいかな"},"kind":"dialogue"},{"uid":"talk.vc.home_kirito_alo_wedding_wait_3#originalText","id":"talk.vc.home_kirito_alo_wedding_wait_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"谢谢你总是在我身边。以后也要继续待在我身边哦！","en":"Thank you for always being there by my side. Here's to more memories together.","ja":"いつも側にいてくれてありがとうこれからも一緒にいてくれ"},"kind":"dialogue"},{"uid":"talk.vc.home_kirito_uw_2022_new_year_wait_1#originalText","id":"talk.vc.home_kirito_uw_2022_new_year_wait_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"果然日本人不管男或女就是要穿和服呢！感觉精神都来了！","en":"Japanese folks just love their Kimono. That's men and women alike! Makes you feel proper!","ja":"やっぱり日本人は男も女も和装だよな!気が引き締まるぜ!"},"kind":"dialogue"},{"uid":"talk.vc.home_kirito_uw_2022_new_year_wait_2#originalText","id":"talk.vc.home_kirito_uw_2022_new_year_wait_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我们去新年参拜吧！！啊，所谓的新年参拜，是指刚过新年就去跟神明许愿啦。","en":"Wanna go hatsumode? What's that? It's where you go pray at a shrine on new year's!","ja":"一緒に初詣行こうぜあ、初詣っていうのは、新年最初に神様にお願いをすることなんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_kirito_uw_2022_new_year_wait_3#originalText","id":"talk.vc.home_kirito_uw_2022_new_year_wait_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"日式板羽球也是需要诀窍的啊，感觉再一下子就可以抓到那感觉了……好！再战一次！","en":"Hagoita is harder than it looks. But I think I'm getting the hang of it? Let's play again!","ja":"羽子板もコツがいるよなもう少しでなんか掴めそうな気が……よし、もう一戦しようぜ!"},"kind":"dialogue"},{"uid":"talk.vc.home_kirito_uw_2022_new_year_wait_4#originalText","id":"talk.vc.home_kirito_uw_2022_new_year_wait_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嘻嘻嘻……球要是再掉下一次，我就要把你的鼻头全画成黑色了啊！","en":"Heh. Drop the shuttle again and I'll paint your nose black!","ja":"ふっふっふっ……次、羽根を落としたら今度は鼻の頭を真っ黒にしてやるぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_kirito_uw_2022_new_year_touch_1#originalText","id":"talk.vc.home_kirito_uw_2022_new_year_touch_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"还真是没什么机会配戴这种形状的帽子啊！有种变装感呢！","en":"Not every day you get to wear a hat like this. Feels kinda like playing dress-up!","ja":"こういう形の帽子ってなかなか被る機会がないよちょっと仮装気分だな"},"kind":"dialogue"},{"uid":"talk.vc.home_kirito_uw_2022_new_year_touch_2#originalText","id":"talk.vc.home_kirito_uw_2022_new_year_touch_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"因为日式板羽球的比赛活动了不少，衣服是不是也乱了呀……","en":"My clothes are all messed up! Too much hagoita will do that though, I guess.","ja":"羽子板勝負で結構動いたからちょっと着崩れちゃったかな……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_1st_1#originalText","id":"talk.vc.home_wait_kirito_1st_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不知不觉也相处很久了耶，我们已经算是一体同心啰。","en":"We've been together for quite a while now. We're completely in sync.","ja":"もうずいぶん一緒にいるな俺らはもう、一心同体だ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_1st_2#originalText","id":"talk.vc.home_wait_kirito_1st_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"尽头山脉的对面到底有多广阔啊……有天真想亲眼看看。","en":"I wonder just how far beyond the End Mountains we can go? I'd love to head there someday.","ja":"果ての山脈の向こうってどのくらい広がってるんだろういつか、見てみたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_1st_3#originalText","id":"talk.vc.home_wait_kirito_1st_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"想不到学校会让人这么开心耶。还是说，是因为跟你一起的关系吗？","en":"I never knew school could be this much fun! Or maybe it's just fun because you're here with me.","ja":"学校ってこんなに楽しいんだなそれとも、君と一緒にいるからかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_1st_4#originalText","id":"talk.vc.home_wait_kirito_1st_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"得帮剑取个名字才行……但实在很难想啊。","en":"I need to name my sword. But I'm having a hard time making a decision.","ja":"剣の名前、決めないといけないんだけど……なかなか決まらないんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_1st_9#originalText","id":"talk.vc.home_wait_kirito_1st_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……呼啊～安静下来后就开始想睡了。","en":"Ahh... Being quiet like this sure makes me sleepy.","ja":"……ふわあ静かにしているとなんだか眠くなってくるよな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_1st_1#originalText","id":"talk.vc.home_touch_kirito_1st_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"啊，我头发又睡乱了吗？……这样有弄好吗？","en":"Oh, do I have a cowlick again? Is it gone now?","ja":"あ、また変な寝癖ついてたか?……直ったかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_1st_2#originalText","id":"talk.vc.home_touch_kirito_1st_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好想再长高一点喔……要是能用《心意》变高就轻松多了……","en":"I wish I were a little taller. If I could use my Incarnation to grow, life would be so much easier.","ja":"もうちょい身長がほしいよな《心意》でデカくなれたら苦労はないのになあ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_1st_4#originalText","id":"talk.vc.home_touch_kirito_1st_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我有没有变比较强壮啊？欸，你帮我摸摸看。","en":"I think my muscles have gotten bigger. Wanna feel 'em?","ja":"少しはたくましくなったかな?ほら、触ってみてくれよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_1st_5#originalText","id":"talk.vc.home_touch_kirito_1st_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"唔哇，被你发现我肚子在叫了？我有点饿了嘛……","en":"Oops, you heard my stomach growl? Yeah, I'm pretty hungry.","ja":"うわ、お腹鳴ったのバレた?なんだか腹減っちゃってさ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_1st_6#originalText","id":"talk.vc.home_touch_kirito_1st_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"哦，要打一场吗！？要切磋的话我随时欢迎喔！","en":"Oh, you wanna rumble?! I'm always up for a good sparring session!","ja":"お、やるか!?立ち合いなら、いつでも歓迎だぜ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_1st_1#originalText","id":"talk.vc.home_time_kirito_1st_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"很好，今天比较早起喔。偶尔这样也不错。","en":"Great, managed to get up nice and early today. It's not a bad thing every once in a while.","ja":"よし、今日は早く起きたぞたまには悪くないな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_1st_4#originalText","id":"talk.vc.home_time_kirito_1st_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不知不觉已经中午啦？一不小心就太专心练习了……这么说来，肚子好饿啊！","en":"Wow, noon already? Got caught up in my training... Didn't realize I was so hungry!","ja":"いつの間にか、もう昼か稽古に夢中になっちゃって……そういえば腹が減ってたよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_1st_7#originalText","id":"talk.vc.home_time_kirito_1st_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这种宁静的夜晚总会令人想起很多事情。","en":"When the night's quiet like this, all my old memories come back to me.","ja":"こんな静かな夜はいろいろと思い出しちゃうんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_1st_10#originalText","id":"talk.vc.home_time_kirito_1st_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"为什么宵夜这么好吃呢……来，快吃吧！","en":"Midnight snacks... Why are they so good? Come on, eat up!","ja":"夜中に食べる食事はなんでこんなにうまいんだろうな……ほら、食えよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_1st_1#originalText","id":"talk.vc.home_day_kirito_1st_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"从今天开始努力加油啰！这周也一样靠气势撑过去吧！","en":"Let's put in another hard day's work and keep up that momentum through the rest of the week!","ja":"今日から張り切っていくか!勢いで今週も乗り切ろう!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_1st_2#originalText","id":"talk.vc.home_day_kirito_1st_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"忙归忙，但是这样也不错。因为一旦闲下来，就不禁会想起很多事。","en":"I've got a lot on my plate, but I like to keep busy so my mind won't go to dark places.","ja":"忙しいけど、それも悪くない暇だと、いろんなことを思い出しちゃうから"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_1st_3#originalText","id":"talk.vc.home_day_kirito_1st_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"既然放假了，就久违地悠哉放松一下吧。一整天无所事事也是不错的喔。","en":"It's our day off, so let's take it easy. Lazy days are the best!","ja":"休みだから、久しぶりにのんびりしようか何もしない日ってのも、いいぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_1st_4#originalText","id":"talk.vc.home_day_kirito_1st_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"假日的夜晚总会让人难以入睡耶。但要是不早点睡的话，明天可就糟糕了。","en":"It's sure hard to fall asleep the night after a day off. I'll pay for it tomorrow, though.","ja":"休みの日の夜ってなかなか眠れないよな早く寝ないと、明日大変なんだけど"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_1st_1#originalText","id":"talk.vc.home_season_kirito_1st_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"春天就是要赏花才对嘛。这边的樱花看起来也非常美喔。","en":"I love seeing all the flowers in the spring. The sakura here in this world are just as pretty.","ja":"春はやっぱりお花見だよなこっちの桜も、かなり綺麗に見えるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_1st_2#originalText","id":"talk.vc.home_season_kirito_1st_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"真希望将来有一天能够和学姊还有罗妮耶她们一起去夏至祭典……","en":"Someday, I hope that I can go to the Summer Festival with Liena, Ronie, and the others.","ja":"夏至祭、いつか先輩やロニエたちとも一緒に行けたらいいな"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_1st_3#originalText","id":"talk.vc.home_season_kirito_1st_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"说到秋天，就会联想到食欲之秋呢。好，来边走边吃吧！","en":"If you ask me, autumn is all about the feasting. Let's take a stroll and get some snacks!","ja":"俺はやっぱり、食欲の秋かなよし、食べ歩きに行こうぜ!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_kirito_1st_4#originalText","id":"talk.vc.home_season_kirito_1st_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"冬季的天空好美啊。因为到了晚上，就几乎没有照明了。","en":"Winter skies sure are pretty. Probably because they really get dark at night.","ja":"冬の空は綺麗だな夜になると、明かりはほとんど消えちゃうからな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_klein_os_1#originalText","id":"talk.vc.home_wait_klein_os_1","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"我平常不太做运动，所以偶尔来AR活动一下身体也是件好事啊！","en":"I'm not the physical type to begin with, so it's nice to be able to move your body around in AR!","ja":"普段は運動不足だからよたまにはARで体を動かすってのもいいもんだよな!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_klein_os_2#originalText","id":"talk.vc.home_wait_klein_os_2","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"等一下我们风林火山的成员会一起去烤肉。你要不要一起去？","en":"After this, I'll be going out for BBQ beef with a member of Fuurinkazan. Want to tag along?","ja":"この後、風林火山のメンバーで焼き肉に行くんだ一緒にどうだ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_klein_os_3#originalText","id":"talk.vc.home_wait_klein_os_3","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"呐，我会负责开车的，下次再一起去打头目战吧！","en":"Hey, I'll bring out the car! Let's go do a Boss Battle again!","ja":"なあ、車出すからよまた一緒にボス戦に行こうぜ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_klein_os_4#originalText","id":"talk.vc.home_wait_klein_os_4","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"再等一下好吗。我们的成员还没到齐。","en":"Wait up! Our member isn't here yet.","ja":"ちょっと待ってくれまだうちのメンバーがそろってないんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_klein_alo_2022_new_year_wait_1#originalText","id":"talk.vc.home_klein_alo_2022_new_year_wait_1","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"新年要结束还早呀！来啦，喝一杯啦！在这边的话你就也能喝吧？","en":"New year's ain't over yet! C'mon. Let's have a glass or two. You can drink this, right?","ja":"まだまだ正月気分だな!まぁ、一杯飲んでけよこっちならオメエも飲めるだろ?"},"kind":"dialogue"},{"uid":"talk.vc.home_klein_alo_2022_new_year_wait_2#originalText","id":"talk.vc.home_klein_alo_2022_new_year_wait_2","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"虎纹感觉是个好兆头啊！我的男子气概感觉更上层楼了！","en":"Stripes are good luck right? Gonna make me look even cooler, I bet.","ja":"虎柄なんて縁起が良さそうだよな男前がまた上がっちまうぜ!"},"kind":"dialogue"},{"uid":"talk.vc.home_klein_alo_2022_new_year_wait_3#originalText","id":"talk.vc.home_klein_alo_2022_new_year_wait_3","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"今年也要奋力前进哦！风林火山！如同烈火般全力进攻！！","en":"Here's to the new year! And may we attack it with the fury of fuurinkazan!","ja":"今年も気張ってくぜ!風林火山、烈火のように全力で攻めあるのみよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_2nd_anniv_1#originalText","id":"talk.vc.home_wait_leafa_alo_2nd_anniv_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我已经受够那些大风大浪了，我想永远保持这样，跟你一起过着和平的时光。","en":"No turbulence for me, thank you. I'd much rather have a looong stretch of peace like this.","ja":"もう波瀾万丈はいらないよずっとこうして一緒に平和な時間を過ごしたい"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_2nd_anniv_2#originalText","id":"talk.vc.home_wait_leafa_alo_2nd_anniv_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"VR游戏形形色色，但如果要体验翱翔天际的快感，我觉得《ALO》一定是最好玩的。","en":"VR games come in all sizes, but nothing beats the feeling of flying in ALO!","ja":"VRゲームは色々あるけど空を飛ぶ快感は《ALO》が絶対一番楽しいと思う"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_2nd_anniv_3#originalText","id":"talk.vc.home_wait_leafa_alo_2nd_anniv_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"欸，我们来比赛吧！从这里飞到森林的另一端，看谁最先抵达终点！","en":"C'mon, let's race! Last one to the opposite edge of the forest loses!","ja":"ねえ、競争しようよ!ここから森の端まで飛んでどっちが先にゴールするか!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_2nd_anniv_4#originalText","id":"talk.vc.home_wait_leafa_alo_2nd_anniv_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"你真的很喜欢穿得全身黑耶，偶尔换换其他色调怎么样？我来帮你搭配！","en":"You really do love to wear black, eh? A little color wouldn't kill you. Come on, let's dress you up!","ja":"ほんとに、黒い格好好きだよねたまには他の色も試したらどうかなあたしがコーディネートしてあげる!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_2nd_anniv_5#originalText","id":"talk.vc.home_wait_leafa_alo_2nd_anniv_5","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我们明明住在同一个家，却像这样在虚拟世界里碰面，感觉真怪。","en":"Here we are, together in VR while our bodies are also together at home... Wild, right?","ja":"あたしたちの体は同じ家にあるのにこうやって仮想世界の中で会うのってなんだか変な気持ち"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_2nd_anniv_6#originalText","id":"talk.vc.home_wait_leafa_alo_2nd_anniv_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天要全家人一起吃晚餐，时间一到你就要跟我一起注销喔！","en":"Don't forget, we're having dinner with the parents today, so we're logging out together when it's time!","ja":"今日は家族で晩ご飯だから時間になったら一緒にログアウトすること!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_2nd_anniv_7#originalText","id":"talk.vc.home_wait_leafa_alo_2nd_anniv_7","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我也来磨练一下料理技能好了。我也想让哥哥尝尝看自己做的菜嘛……","en":"Maybe I should put more points in my cooking skills, too? 'Cause... I'd love for you to eat my cooking.","ja":"あたしも、料理スキル伸ばしてみようかな。だって、お兄ちゃんに料理を食べてもらいたいし……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_2nd_anniv_8#originalText","id":"talk.vc.home_wait_leafa_alo_2nd_anniv_8","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"取消速限之后，飞行的速度变得比以前快多了，这个更新真是太棒了！","en":"With the speed limit gone, I can fly much faster than before. Awesome update, right?!","ja":"速度制限がなくなって、前よりずっと速く飛べるようになったんだ最高のアップデートだよね!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_2nd_anniv_9#originalText","id":"talk.vc.home_wait_leafa_alo_2nd_anniv_9","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"你是不是累了？这样的话，就回到现实世界，吃个点心放松一下吧。","en":"Are you tired? Let's go back to the real world, lie down, and eat junk food!","ja":"もしかして、疲れちゃった?だったら、リアルに戻ってゆっくりおやつでも食べようよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_alo_2nd_anniv_1#originalText","id":"talk.vc.home_touch_leafa_alo_2nd_anniv_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"这么大的缎带，我在想看起来会不会很孩子气……你觉得呢？有成熟的感觉吗？","en":"Is the big ribbon a bit babyish? Well? What do you think? Do I look like an adult?","ja":"おっきいリボンって子どもっぽいかなとも思ったんだけど……どうかな? 大人っぽく見える?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_alo_2nd_anniv_2#originalText","id":"talk.vc.home_touch_leafa_alo_2nd_anniv_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"……再多摸一下。是你先动手的，你要负起责任，摸到我满意为止。","en":"Ooh, more pats, please... Hey, you started it. You gotta see it through until I'm satisfied.","ja":"……もっと撫でて始めたのはそっちなんだから責任とって、あたしが満足するまでね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_alo_2nd_anniv_3#originalText","id":"talk.vc.home_touch_leafa_alo_2nd_anniv_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"在VR的世界里用不着担心痘痘之类的，真是太好了。巧克力也能吃个过瘾。","en":"One of the great perks of VR is not needing to worry about acne! I can eat all the chocolate I want.","ja":"VRだと、ニキビの心配とかしなくていいから助かるよチョコだってたくさん食べられるし"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_alo_2nd_anniv_4#originalText","id":"talk.vc.home_touch_leafa_alo_2nd_anniv_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"等、等一下！就算这是在《ALO》里面，你也不能突然就摸我啊！","en":"D-Dude! I know we're in ALO and all, but hands off!","ja":"ちょ、ちょっと!いくら《ALO》の中だからっていきなり触るのはダメだよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_alo_2nd_anniv_5#originalText","id":"talk.vc.home_touch_leafa_alo_2nd_anniv_5","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"……别看这样，其实已经比现实中的我来得小一点了，活动起来也比较轻松一些。","en":"Hard to believe, I know, but they're actually a bit smaller in this world. It's much easier to move here.","ja":"……これでも、現実よりはちょっとだけ小さいから、動くときも少し楽なんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_alo_2nd_anniv_6#originalText","id":"talk.vc.home_touch_leafa_alo_2nd_anniv_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"……你既然敢这么做，那我也不是没有办法治你。看我在现实世界怎么报复回去。","en":"Hey, keep that up much longer, and you're gonna give me ideas. When we're IRL, it's payback time.","ja":"……そういうことされるとあたしにだって考えがあるからねリアルで仕返ししちゃうんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_alo_2nd_anniv_7#originalText","id":"talk.vc.home_touch_leafa_alo_2nd_anniv_7","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我已经不是小孩子了，你不可以再这样摸我。还是说，你摸的时候……是把我当大人在看？","en":"Hey, I'm not a little girl anymore— so don't touch me like that! Unless... that was a grown-up touch?","ja":"もう小さい子どもじゃないんだからそんなふうに触っちゃダメそれとも大人として……触ってるの?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_alo_2nd_anniv_8#originalText","id":"talk.vc.home_touch_leafa_alo_2nd_anniv_8","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"你对其他人也会做这种事？我是可以原谅你，但换成别人可就没那么容易了喔。","en":"So, do you do this to others? I'll cut you some slack, but the others might not be so forgiving.","ja":"こんなこと、他の人にもしてるの?あたしだから許してあげるけど他の人はそうはいかないんだからね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_2nd_anniv_1#originalText","id":"talk.vc.home_time_leafa_alo_2nd_anniv_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"早安，你今天真早起呢。趁着精神正好，陪我一起做剑道的晨练吧！","en":"Good morning—up early today, I see. Why don't you come practice some kendo with me!","ja":"おはよう、今日は早起きだねその調子で剣道の朝練も一緒にやろうよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_2nd_anniv_2#originalText","id":"talk.vc.home_time_leafa_alo_2nd_anniv_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"早晨的空气真的很棒呢，还感受得到一些夜晚的寒冷，让人神清气爽。","en":"I just love the morning air, don't you? Nice and chilly from the night— really clears my head!","ja":"朝の空気っていいよねまだ少し夜の冷たさが残ってて頭がシャキッてなるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_2nd_anniv_3#originalText","id":"talk.vc.home_time_leafa_alo_2nd_anniv_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"啊～你果然还在睡！喂，该起床了啦，今天要一起解任务。","en":"Ah-hah! I knew you'd still be in bed! Come on, get up. You're going on that quest with me today.","ja":"あー、やっぱりまだ寝てる!ほら、もう起きてよ今日は一緒にクエストするんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_2nd_anniv_4#originalText","id":"talk.vc.home_time_leafa_alo_2nd_anniv_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"剑道的刺击，在社团里很难找到机会练习，所以我想在这边试试看。","en":"I have a hard time practicing my kendo forms at school, so I was thinking of trying it here.","ja":"剣道の突きって、なかなか部活では練習できないからここでやってみようと思うんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_2nd_anniv_5#originalText","id":"talk.vc.home_time_leafa_alo_2nd_anniv_5","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"艾恩葛朗特的区域是不错，但偶尔要不要去地上看看？那里也有些好玩的地方。","en":"Aincrad is nice and all, but don't you want to go above ground? There's some pretty fun places.","ja":"アインクラッドのエリアもいいけどたまには地上にも行ってみない?けっこう楽しい場所もあるし"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_2nd_anniv_6#originalText","id":"talk.vc.home_time_leafa_alo_2nd_anniv_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"天气这么好，让人想要朝着太阳尽情地飞翔呢。","en":"Nice clear days like this just make me wanna fly straight up to the sun!","ja":"こんな天気のいい日は太陽に向かって思いっきり飛びたくなるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_2nd_anniv_7#originalText","id":"talk.vc.home_time_leafa_alo_2nd_anniv_7","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"明明是在现实世界的早上登录的，到了游戏里时间却是晚上，生理时钟都要乱掉了呢。","en":"Logging into the game in the morning when it's night in-game sure throws off my internal clock.","ja":"リアルでは朝にログインしたのにゲームの中が夜の時間だと体内時計が狂っちゃうよね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_2nd_anniv_8#originalText","id":"talk.vc.home_time_leafa_alo_2nd_anniv_8","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我啊，非常喜欢《ALO》的夜景。梦幻的景色，让人看了心动不已。","en":"Boy, do I love the nightscape in ALO! It's so magical and romantic.","ja":"《ALO》の夜景って、あたし大好きなんだ。幻想的でなんだかドキドキしちゃう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_2nd_anniv_9#originalText","id":"talk.vc.home_time_leafa_alo_2nd_anniv_9","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"白天的天空虽然也很不错，但在夜空中飞翔也别有一番乐趣呢。","en":"The day time is nice, but the night sky sure gives flying a whole new level of fun.","ja":"昼間の空もいいけど、夜の空を飛ぶのは、また違った楽しさがあるんだよね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_2nd_anniv_10#originalText","id":"talk.vc.home_time_leafa_alo_2nd_anniv_10","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"这么晚了还在玩游戏。……啊，我也没有资格讲你呢，呵呵。","en":"Gaming? This late at night? Wait, I guess I shouldn't be the one to lecture you! Haha.","ja":"こんな時間にゲームなんて……って、あたしも人のこと言えないか、ふふ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_2nd_anniv_11#originalText","id":"talk.vc.home_time_leafa_alo_2nd_anniv_11","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"有些话就算在现实世界里说不出口，到了这个世界也能诚实地讲出来呢。尤其是在夜深人静的时候……","en":"This world always makes me open up and say what's on my mind... especially late at night.","ja":"こっちの世界だと、リアルで言えないことも、素直に話せるよね特に深夜は……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_2nd_anniv_12#originalText","id":"talk.vc.home_time_leafa_alo_2nd_anniv_12","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"要不要一起去看看晚上的世界树？听说景色很棒，也有很多游客。……还、还有情侣。","en":"Wanna go see The World Tree with me? It's so pretty at night, that...c-couples like to go there.","ja":"夜の世界樹、ふたりで行ってみない?景色がよくて、見物人も多いんだって……か、カップルとかも"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_alo_2nd_anniv_1#originalText","id":"talk.vc.home_day_leafa_alo_2nd_anniv_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"星期一还是不免感到忧郁……真希望星期一的上课时间可以往后延个一小时左右啊。","en":"I have a bad case of the Mondays... I wish they'd at least start class an hour later or something.","ja":"月曜日はやっぱり憂鬱かも……月曜の始業時間、1時間くらい遅くして欲しいよね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_alo_2nd_anniv_2#originalText","id":"talk.vc.home_day_leafa_alo_2nd_anniv_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"最近就连在社团练剑的时候，我都会忍不住思考，刚才练习的动作或许能用在游戏的战斗上。","en":"I can't do kendo at school anymore without thinking, \"Ooh! I could use this in my next battle...\"","ja":"最近は部活をやってても今の動きはバトルに使えるかもとか考えるようになっちゃった"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_alo_2nd_anniv_3#originalText","id":"talk.vc.home_day_leafa_alo_2nd_anniv_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"久违的假期～咦？当然算久违啊，我已经等了一整周了。","en":"We haven't had time off in a while. Huh? It has sooo been a while! I've been waiting all week for this.","ja":"久しぶりのお休みだねーえ? 久しぶりだよだって1週間も待ったんだもん"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_alo_2nd_anniv_4#originalText","id":"talk.vc.home_day_leafa_alo_2nd_anniv_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"清醒时总会觉得星期日还没结束，然后不知不觉就熬夜了。明明隔天会困到不行……","en":"I never want Sundays to end, so I always stay up super late... even though I'll regret it on Monday.","ja":"起きてる間は日曜が続く気がしてなんとなく夜更かししちゃうんだよね明日絶対眠いのに……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_2nd_anniv_1#originalText","id":"talk.vc.home_event_leafa_alo_2nd_anniv_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"新年快乐，今年一整年也请多多指教啰。不论是作为家人，还是作为伙伴。","en":"Happy New Year! Let's make it a good one. With our friends and family alike.","ja":"あけましておめでとう今年も一年よろしくね家族としても、仲間としても"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_2nd_anniv_2#originalText","id":"talk.vc.home_event_leafa_alo_2nd_anniv_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"啊，我忘记买节分的豆子了，妈妈明明有吩咐我！我得赶快去买才行！","en":"Oh, shoot! Mom asked me to buy beans for Setsubun and I totally forgot! I'd better go now!","ja":"あ、節分のお豆買ってきてってお母さんに言われたのに忘れてた! 買いに行かないと!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_2nd_anniv_3#originalText","id":"talk.vc.home_event_leafa_alo_2nd_anniv_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"来，在这个世界也给你巧克力。回到家后，我还会再给你真的巧克力哦。","en":"Here's some Valentine's chocolate! But I'll have some \"real\" chocolate for you when we get home.","ja":"はい、こっちでもチョコレートリアルに戻ったら、そっちにも本物のチョコがあるからね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_2nd_anniv_4#originalText","id":"talk.vc.home_event_leafa_alo_2nd_anniv_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"真希望女儿节娃娃能一直摆在外面。每次只要节庆结束，就会立刻收起来。","en":"I wish we could keep Hinamatsuri dolls up all year, instead of putting them away the next day.","ja":"おひな様、ずっと飾っておければいいのにねいつも、終わるとすぐ片付けちゃうし"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_2nd_anniv_5#originalText","id":"talk.vc.home_event_leafa_alo_2nd_anniv_5","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"谢谢你的回礼。那我们就一起吃这个吧。没关系，我就想和你一起吃。","en":"Thanks for the White Day gift. Wanna share it with me? C'mon, I wanna eat it together.","ja":"お返しありがとうそれじゃコレ、一緒に食べようかいいの、ふたりで一緒に食べたいんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_2nd_anniv_6#originalText","id":"talk.vc.home_event_leafa_alo_2nd_anniv_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"就算今天是愚人节，你也不可以在家对我恶作剧哦，我会吓到的。","en":"Don't use April Fools' Day as an excuse to prank me when we get home. I don't wanna freak out.","ja":"エイプリルフールだからって家にいたずら仕掛けるのはやめてね。びっくりしちゃう"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_2nd_anniv_7#originalText","id":"talk.vc.home_event_leafa_alo_2nd_anniv_7","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"连假我要大玩特玩！这次社团也放假，时间可以随我分配！","en":"It's a long vacation—time to party! I don't have kendo practice either, so I'll be free as a bird!","ja":"連休は思いっきり遊ぶんだ!今回は部活もお休みだしずっと自由だから!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_2nd_anniv_8#originalText","id":"talk.vc.home_event_leafa_alo_2nd_anniv_8","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"这个季节穿道服很痛苦。马上就会满身大汗，全身湿湿黏黏的。","en":"I hate wearing my kendo uniform in this humidity. I get sticky with sweat in like five minutes.","ja":"この季節は、胴着を着るのが辛いんだ。すぐに汗で蒸れてジメジメしちゃうし"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_2nd_anniv_9#originalText","id":"talk.vc.home_event_leafa_alo_2nd_anniv_9","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"欸，你还记得小时候写在短签上的愿望吗？我……从来没有忘过喔。","en":"Do you remember what you wished for on Tanabata when you were little? Well...I do.","ja":"ねえ、小さい頃短冊に書いたお願い、覚えてる?あたしは……ずっと覚えてるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_2nd_anniv_10#originalText","id":"talk.vc.home_event_leafa_alo_2nd_anniv_10","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"真想再全家一起去海水浴场呢。我现在已经可以下水了，应该能玩得比之前更开心！","en":"I miss our family trips to the beach. Plus, I think we'd have even more fun, now that we're older!","ja":"また家族で海水浴行きたいな今なら海に入っても大丈夫だし前より楽しめると思う!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_2nd_anniv_11#originalText","id":"talk.vc.home_event_leafa_alo_2nd_anniv_11","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"暑假要结束了呢。不过今年玩得很过瘾，所以不太会觉得失落。","en":"Summer vacation's almost over. Sucks, right? But at least we had plenty of fun times this year.","ja":"夏休み、終わっちゃうねでも今年はたっぷり遊んだからあんまり寂しくないかも"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_2nd_anniv_12#originalText","id":"talk.vc.home_event_leafa_alo_2nd_anniv_12","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"只有我跟你一起赏月，这是不是第一次啊？呵呵，真开心……可以两人世界。","en":"This just might be the first time we've moon-gazed together like this. Heehee...just you and me.","ja":"ふたりっきりで月を見るのってもしかしたら初めてかなふふ、うれしいな……ふたりきり"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_2nd_anniv_13#originalText","id":"talk.vc.home_event_leafa_alo_2nd_anniv_13","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"那个大南瓜，哪里有在卖啊？我还满想戴看看的。","en":"Where do you think they sell huge pumpkins like that? I'd love to wear one on my head at least once.","ja":"あのおっきいカボチャってどこに売ってるんだろうね一度かぶってみたいんだ、アレ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_2nd_anniv_15#originalText","id":"talk.vc.home_event_leafa_alo_2nd_anniv_15","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"不管在那边还是这边都有蛋糕吃，今天真是幸福啊。而且圣诞树也很漂亮呢。","en":"I get to eat Christmas cake in-game and at home, I've got a pretty tree— what'd I do to deserve such bliss?","ja":"向こうでもこっちでもケーキを食べて、今日は幸せだなあツリーもキレイだしね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_alo_2nd_anniv_1#originalText","id":"talk.vc.home_season_leafa_alo_2nd_anniv_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"就算是在这个世界，春天的森林也很美呢。百花盛开，有春天的气息。","en":"Forests in the spring are just as pretty in this world, aren't they? So many fragrant flowers.","ja":"こっちの世界でも、春の森はキレイだよね。いろんな花が咲いて春の匂いがする"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_alo_2nd_anniv_2#originalText","id":"talk.vc.home_season_leafa_alo_2nd_anniv_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"这几年的夏天真的很热耶……就算在社团练习时喝水也都不会被骂了。","en":"It's been so hot lately that my kendo teacher stopped yelling at us for drinking water during practice.","ja":"最近の夏は、すごく暑いよねー……部活の稽古中にお水飲んでも怒られなくなったし"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_alo_2nd_anniv_3#originalText","id":"talk.vc.home_season_leafa_alo_2nd_anniv_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"读书之秋、食欲之秋，秋天有好多种样貌，哥哥你喜欢哪种呢？","en":"In Japan, we often say \"Autumn of Reading\" or \"Autumn of Appetite,\" but what's autumn to you?","ja":"読書の秋とか、食欲の秋とかいろんな秋があるけどお兄ちゃんはどんな秋が好き?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_alo_2nd_anniv_4#originalText","id":"talk.vc.home_season_leafa_alo_2nd_anniv_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"呜～天气一直这么冷的话，会让人不想回到现实啊。毕竟这边气候暖和又舒服。","en":"Blerrrg. If it keeps freezing so hard, I'll never want to go back to the real world. It's nice and warm here.","ja":"寒い日が続くとリアルに戻りたくなくなっちゃうよこっちは暖かくて気持ちいいし"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_2nd_anniv_2#originalText","id":"talk.vc.home_bd_leafa_alo_2nd_anniv_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"能在生日这天跟你独处，我真的好高兴……两人独享的时光，就是最好的礼物。","en":"Alone with you on my birthday? What a treat! Quality time with you... That's the best gift I could ask for.","ja":"誕生日にふたり、なんてすごくうれしい……ふたりきりの時間が一番のプレゼントだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_2nd_anniv_3#originalText","id":"talk.vc.home_bd_leafa_alo_2nd_anniv_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"哥哥今天生日，我要煮大餐给他吃。当然，蛋糕我也会自己做喔！","en":"I'm gonna cook you a huge feast for your birthday. Cake and all— homemade, of course!","ja":"お兄ちゃんの誕生日はご馳走を作るんだもちろん、ケーキも手作りだよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_2nd_anniv_5#originalText","id":"talk.vc.home_bd_leafa_alo_2nd_anniv_5","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"爱丽丝小姐的生日到了呢。那就再邀她来我们家吧，爸爸和妈妈一定也会很高兴的。","en":"It's Alice's birthday today, right? You should invite her over again! Mom and Dad would love that.","ja":"アリスさん、お誕生日なんだよねなら、またうちに招待すればお父さんお母さんも喜ぶよ、きっと"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_2nd_anniv_6#originalText","id":"talk.vc.home_bd_leafa_alo_2nd_anniv_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"要送亚丝娜小姐的礼物，你准备好了吗？你应该不至于……什么都还没准备吧？","en":"Did you make sure to get Asuna a birthday present? Come on, please say you did...","ja":"アスナさんへのプレゼントちゃんと用意した? まさかまだ……なんてことはないよね?"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_2nd_anniv_8#originalText","id":"talk.vc.home_bd_leafa_alo_2nd_anniv_8","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"诗乃小姐的生日，就送她饰品装备好了。她之前有说过自己正在找。","en":"I'm thinking of getting Sinon some weapon accessories for her birthday. She said she was looking for some.","ja":"シノンさんの誕生日はアクセサリー装備を贈ろうかなこの間探してるって言ってたから"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_2nd_anniv_9#originalText","id":"talk.vc.home_bd_leafa_alo_2nd_anniv_9","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"有纪小姐的生日，就找沉睡骑士的成员一起庆祝，热闹一下吧！","en":"For Yuuki's birthday, let's round up the Sleeping Knights and throw a big bash!","ja":"ユウキさんの誕生日はスリーピング・ナイツの人たちと一緒に、賑やかにお祝いしようよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_2nd_anniv_14#originalText","id":"talk.vc.home_bd_leafa_alo_2nd_anniv_14","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"莉兹的生日，大家决定要各自带料理去开派对。哥哥你也要做好准备喔！","en":"For Liz's birthday, we're gonna have a potluck. Don't forget to bring something!","ja":"リズさんの誕生日、みんなでご飯を持ち寄ってパーティーなんだお兄ちゃんも、ちゃんと用意してね!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_2nd_anniv_15#originalText","id":"talk.vc.home_bd_leafa_alo_2nd_anniv_15","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"西莉卡绑起双马尾非常可爱，所以我想送她发饰。我已经找到一个很棒的发饰啰！","en":"Since Silica's pigtails are so cute, I'm gonna get her some bows. I found some really pretty ones!","ja":"シリカちゃん、ツインテールがすごくかわいいから、髪飾りを贈るんだ。ステキな物を見つけたの!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_leafa_alo_2nd_anniv_1#originalText","id":"talk.vc.home_etc_leafa_alo_2nd_anniv_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"解任务辛苦了。你最近一直在忙攻略的事，今天就好好休息吧。","en":"Good job, trooper! That quest sure took a while. So just take it easy today, you hear?","ja":"クエストクリア、お疲れさまずっと攻略してたんだから今日はゆっくり休んでね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_leafa_alo_2nd_anniv_2#originalText","id":"talk.vc.home_etc_leafa_alo_2nd_anniv_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"快看，有礼物喔！不快点拆开的话，说不定就会超过领取期限了！","en":"A gift just came for you! Hurry and open it before it's too late!","ja":"ほら、贈り物だよ!早く開けないと、受取期間過ぎちゃうかも!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_leafa_alo_2nd_anniv_3#originalText","id":"talk.vc.home_etc_leafa_alo_2nd_anniv_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"新任务好像开始了，我们可不能落于人后，准备起跑冲刺啰！","en":"A new quest just started, so we'd better jump on it! I don't wanna be left in the dust.","ja":"新しいクエストが始まったみたい乗り遅れないよう、あたしたちもスタートダッシュだよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_tales_1#originalText","id":"talk.vc.home_wait_leafa_tales_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"哥哥老是会被卷入这种怪事呢。虽说我早就见怪不怪了啦。","en":"Dang, Kirito, you're always surrounded by eccentric folks. But I'm used to it by now.","ja":"お兄ちゃんって、いつもこういうイレギュラーに巻き込まれるよねもう慣れたけどさ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_tales_2#originalText","id":"talk.vc.home_wait_leafa_tales_2","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"听说这套服装是希侬小姐他们世界里魔法师所穿的服装。","en":"I hear this costume is worn by magic users in Shionne's world.","ja":"この衣装って、シオンさんたちの世界にいる魔法使いの子が着てるものなんだって"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_tales_3#originalText","id":"talk.vc.home_wait_leafa_tales_3","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"希侬小姐身上的〈荆棘〉诅咒……让她连喜欢的人都不能触碰，实在好令人悲伤……","en":"Poor Shionne. Imagine having a thorn curse and not being able to touch the one you love...","ja":"シオンさんの〈荊〉の呪い……好きな人にも触れないなんてやっぱり悲しいよね……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_tales_4#originalText","id":"talk.vc.home_wait_leafa_tales_4","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"我和希侬小姐约好下次要一起学做菜，她说想要在这边学会再回去。","en":"Shionne and I are gonna learn how to cook together. She wants to take our recipes back home with her.","ja":"今度、シオンさんと一緒に料理の勉強することになったのここで覚えて帰りたいんだって"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_tales_5#originalText","id":"talk.vc.home_wait_leafa_tales_5","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"听说奥尔芬先生和希侬小姐分别是达纳人和雷纳人？同样是人类，但人种不同的样子。","en":"Shionne and Alphen are Dahna and...Rena? Apparently they're both human, but different races.","ja":"シオンさんとアルフェンさんはダナとレナ?っていって同じ人間だけど違う人種みたい"},"kind":"dialogue"}]};
